SELECT CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, MAX(age) AS max_age, MIN(signup_date) AS first_signup_date, SUM(CASE WHEN segment = 'Consumer' THEN 1 ELSE 0 END) AS consumer_count FROM customers WHERE credit_limit < 13400 GROUP BY CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING consumer_count >= 42 ORDER BY first_signup_date DESC
